; DSCR.S - DASH SCREEN AND LAYOUT MANAGEMENT

; CLEARSCREEN - FILLS EXACTLY THE 1000 VALID SCREEN/COLOR CELLS.
;
; A NAIVE 4-PAGE INX/BNE LOOP COVERS $0400-$07FF (1024 BYTES), WHICH WRITES
; 24 BYTES PAST THE LAST VALID CELL AT $07E7/$DBE7 (CELLS 1000-1023 DO NOT
; EXIST ON THE 40X25 SCREEN). SPLIT INTO A FULL 3-PAGE LOOP (768 CELLS) PLUS A
; BOUNDED 232-CELL REMAINDER SO THE TOTAL IS EXACTLY 1000, NEVER TOUCHING
; CELL 1000 OR BEYOND.
;
; INPUT: NONE. OUTPUT: NONE. CLOBBERS: A, X.
CLEARSCREEN:
    LDX #0
CLEARLOOP:
    LDA #$20                ; SPACE
    STA $0400, X
    STA $0500, X
    STA $0600, X

    LDA #$0E                ; LIGHT BLUE TEXT COLOR
    STA $D800, X
    STA $D900, X
    STA $DA00, X

    INX
    BNE CLEARLOOP

    LDX #0
CLEARREMLOOP:
    LDA #$20
    STA $0700, X
    LDA #$0E
    STA $DB00, X
    INX
    CPX #232                ; 768 + 232 = 1000 CELLS EXACTLY
    BNE CLEARREMLOOP
    RTS

; SCREENSETCURSOR - VALIDATES AND SETS THE SHARED CURSOR (ZP $72/$77).
;
; INPUT: A = COLUMN (0-39), Y = ROW (0-24).
; OUTPUT: C CLEAR AND CURSOR UPDATED ON SUCCESS. C SET AND NO STATE CHANGE
;         (ZP $72/$77 UNTOUCHED) IF EITHER COORDINATE IS OUT OF RANGE.
; CLOBBERS: A.
SCREENSETCURSOR:
    CMP #40
    BCS SSC_INVALID
    CPY #25
    BCS SSC_INVALID
    STA $77                 ; CURRENTCOL
    STY $72                 ; CURRENTROW
    CLC
    RTS
SSC_INVALID:
    SEC
    RTS

; SCREENPUTCHAR - BOUNDED ONE-CELL WRITE AT THE CURSOR, THEN ADVANCES COLUMN.
;
; INPUT: A = SCREEN-CODE CHARACTER. CURSOR = ZP $72 (ROW), $77 (COL).
; OUTPUT: C CLEAR AND CHARACTER WRITTEN (SCREEN + DEFAULT COLOR), COLUMN
;         ADVANCED BY ONE, IF THE CURSOR WAS IN BOUNDS. C SET AND NO WRITE,
;         COLUMN NOT ADVANCED, IF THE CURSOR WAS OUT OF BOUNDS (E.G. A PRIOR
;         WRITE ALREADY ADVANCED PAST COLUMN 39).
; CLOBBERS: A, Y. PRESERVES X.
SCREENPUTCHAR:
    STA $7D                 ; STASH CHARACTER ACROSS COMPUTEROWADDR
    LDA $77
    CMP #40
    BCS SPC_INVALID
    LDA $72
    CMP #25
    BCS SPC_INVALID
    JSR COMPUTEROWADDR      ; ZP $73/$74 = SCREEN ADDRESS OF CURRENT ROW
    LDA $73
    STA $7B
    LDA $74
    CLC
    ADC #$D4                ; COLOR RAM IS SCREEN RAM + $D400
    STA $7C                 ; ZP $7B/$7C = COLOR ADDRESS OF CURRENT ROW
    LDY $77
    LDA $7D
    STA ($73), Y
    LDA #$0E                ; DEFAULT TEXT COLOR (LIGHT BLUE)
    STA ($7B), Y
    INC $77                 ; ADVANCE COLUMN
    CLC
    RTS
SPC_INVALID:
    SEC
    RTS

; SCREENPUTSTRING - BOUNDED ROW WRITE FROM A NUL-TERMINATED SCREEN-CODE STRING.
;
; INPUT: A = MAXIMUM CHARACTER COUNT REQUESTED BY THE CALLER.
;        X = STRING POINTER LOW, Y = STRING POINTER HIGH.
;        CURSOR = ZP $72 (ROW), $77 (COL).
; OUTPUT: WRITES CHARACTERS FROM (X,Y) UNTIL A $00 TERMINATOR, THE REQUESTED
;         MAXIMUM, OR THE END OF THE ROW (COLUMN 39) IS REACHED, WHICHEVER
;         COMES FIRST. THE REQUESTED MAXIMUM IS ALWAYS CLAMPED TO THE
;         REMAINING COLUMNS SO A ROW CAN NEVER BE CROSSED.
;         C CLEAR IF A $00 TERMINATOR WAS FOUND WITHIN THE BOUND (NORMAL).
;         C SET IF THE BOUND WAS HIT BEFORE A TERMINATOR (TRUNCATED).
; CLOBBERS: A, X, Y.
SCREENPUTSTRING:
    STA $7E                 ; REQUESTED MAX LENGTH
    STX $75
    STY $76                 ; ZP $75/$76 = SOURCE STRING POINTER
    LDA #40
    SEC
    SBC $77                 ; A = COLUMNS REMAINING IN THE ROW
    CMP $7E
    BCS SPS_LENOK            ; REMAINING >= REQUESTED, KEEP REQUESTED LENGTH
    STA $7E                  ; ELSE CLAMP TO REMAINING COLUMNS
SPS_LENOK:
    LDY #0
SPS_LOOP:
    CPY $7E
    BCS SPS_TRUNCATED
    LDA ($75), Y
    BEQ SPS_DONE
    STY $7F                 ; SAVE SOURCE INDEX (SCREENPUTCHAR CLOBBERS Y)
    JSR SCREENPUTCHAR
    LDY $7F
    INY
    JMP SPS_LOOP
SPS_TRUNCATED:
    SEC
    RTS
SPS_DONE:
    CLC
    RTS

DRAWFRAME:
    ; COPY ROW 0 (TOP BORDER)
    LDX #0
ROW0LOOP:
    LDA BORDERROW, X
    STA $0400, X
    INX
    CPX #40
    BNE ROW0LOOP

    ; COPY ROW 1 (TITLE)
    LDX #0
ROW1LOOP:
    LDA TITLEROW, X
    STA $0428, X
    INX
    CPX #40
    BNE ROW1LOOP

    ; COPY ROW 2 (TABS)
    LDX #0
ROW2LOOP:
    LDA TABSROW, X
    STA $0450, X
    INX
    CPX #40
    BNE ROW2LOOP

    ; COPY ROW 3 (BORDER)
    LDX #0
ROW3LOOP:
    LDA BORDERROW, X
    STA $0478, X
    INX
    CPX #40
    BNE ROW3LOOP

    ; COPY ROW 21 (MIDDLE BOTTOM BORDER)
    LDX #0
ROW21LOOP:
    LDA BORDERROW, X
    STA $0748, X
    INX
    CPX #40
    BNE ROW21LOOP

    ; COPY ROW 22 (STATUS BAR)
    LDX #0
ROW22LOOP:
    LDA STATUSROW, X
    STA $0770, X
    INX
    CPX #40
    BNE ROW22LOOP

    ; COPY ROW 23 (BOTTOM BORDER)
    LDX #0
ROW23LOOP:
    LDA BORDERROW, X
    STA $0798, X
    INX
    CPX #40
    BNE ROW23LOOP

    ; DRAW MIDDLE FRAME LINES ON ROWS 4 TO 20
    LDA #4                  ; CURRENT ROW INDEX
    STA $72                 ; ZP $72 = ROW INDEX
DRAWMIDROWS:
    LDA $72
    CMP #21
    BCS DRAWMIDDONE
    
    JSR COMPUTEROWADDR      ; RESULT IN ZP $73/$74
    
    LDY #0
    LDA #$5D                ; SCREEN CODE VERTICAL LINE
    STA ($73), Y
    
    LDA #$20                ; SPACE
    INY
CLEARMIDROWLOOP:
    STA ($73), Y
    INY
    CPY #39
    BCC CLEARMIDROWLOOP
    
    LDA #$5D                ; VERTICAL LINE
    STA ($73), Y
    
    INC $72                 ; NEXT ROW
    JMP DRAWMIDROWS
DRAWMIDDONE:
    JSR HIGHLIGHTTABS
    RTS

; HIGHLIGHTTABS - COLORS THE ACTIVE TAB'S LABEL WHITE, OTHERS LIGHT BLUE.
;
; INPUT: NONE (READS CURRPAGE FROM DDATA.S).
; OUTPUT: ROW 2 COLOR RAM UPDATED FOR ALL THREE TAB LABEL RANGES.
; CLOBBERS: A, X, Y.
HIGHLIGHTTABS:
    LDX #0                  ; TAB INDEX 0..2 (SYSTEM, APPLICATIONS, VMM TEST)
HT_LOOP:
    CPX #3
    BEQ HT_DONE
    LDA #$0E                ; INACTIVE COLOR (LIGHT BLUE)
    CPX CURRPAGE
    BNE HT_COLORSET
    LDA #$01                ; ACTIVE TAB COLOR (WHITE)
HT_COLORSET:
    STA $7D                 ; STASH CHOSEN COLOR
    LDA TABCOLSTART, X
    CLC
    ADC #$50                ; + ROW-2 COLOR OFFSET (ROW 2 * 40 = $50)
    STA $7B
    LDA #$D8
    STA $7C                 ; ZP $7B/$7C = COLOR ADDRESS OF THIS TAB'S FIRST COLUMN
    LDA TABCOLLEN, X
    STA $7E                 ; LENGTH FOR THIS TAB
    LDY #0
HT_FILL:
    CPY $7E
    BCS HT_NEXTTAB
    LDA $7D
    STA ($7B), Y
    INY
    JMP HT_FILL
HT_NEXTTAB:
    INX
    JMP HT_LOOP
HT_DONE:
    RTS

; COMPUTEROWADDR - SCREEN ADDRESS OF ROW IN ZP $72 -> ZP $73/$74.
;
; ROW*40 IS BUILT AS ROW*8 + ROW*32. ROW*8 FITS IN ONE BYTE FOR EVERY LEGAL ROW
; (24*8 = 192), BUT ROW*32 DOES NOT: IT PASSES 255 AT ROW 8 (8*32 = 256). THE
; OVERFLOW MUST THEREFORE BE CARRIED INTO THE HIGH BYTE WITH ROL RATHER THAN
; DISCARDED BY A BARE ASL, OR EVERY ROW FROM 8 DOWN LANDS A FULL PAGE SHORT --
; ROW 8 AT $0440 INSTEAD OF $0540 -- AND THE FRAME DRAWS ON TOP OF ITSELF.
COMPUTEROWADDR:
    LDA #0
    STA $74                 ; HIGH BYTE OF ROW*40, ACCUMULATED VIA ROL BELOW

    LDA $72                 ; ROW
    ASL A                   ; ROW * 2
    ASL A                   ; ROW * 4
    ASL A                   ; ROW * 8  (FITS: MAX 192)
    STA $73

    ASL A
    ROL $74                 ; ROW * 16, OVERFLOW KEPT
    ASL A
    ROL $74                 ; ROW * 32, OVERFLOW KEPT

    CLC
    ADC $73                 ; ROW*32 + ROW*8 = ROW*40 (LOW)
    STA $73
    LDA $74
    ADC #$04                ; + SCREEN BASE $0400, PLUS THE CARRY JUST ABOVE
    STA $74
    RTS
